from dataclasses import dataclass


@dataclass(frozen=True)
class Chunk:
    doc_id: str
    start: int
    end: int
    text: str


def chunk_text(doc_id, text, size, overlap):
    """Splits text into chunks of at most `size` characters.

    Neighbouring chunks share `overlap` characters, so a sentence cut at one chunk's edge is whole in the next.
    """
    if overlap >= size:
        raise ValueError("overlap must be smaller than size")
    chunks = []
    for start in range(0, len(text), size):
        end = min(start + size, len(text))
        chunks.append(Chunk(doc_id, start, end, text[start:end]))
    return chunks

