import unittest

from chunker import chunk_text

TEXT = "Returns are accepted within thirty days of purchase, and refunds go to the original payment method."


class Regression(unittest.TestCase):
    def test_no_chunk_is_longer_than_the_size(self):
        for chunk in chunk_text("p", TEXT, size=40, overlap=20):
            self.assertLessEqual(len(chunk.text), 40)

    def test_the_chunks_cover_the_whole_document(self):
        chunks = chunk_text("p", TEXT, size=40, overlap=20)
        self.assertEqual(chunks[0].start, 0)
        self.assertEqual(chunks[-1].end, len(TEXT))
        for chunk in chunks:
            self.assertEqual(TEXT[chunk.start : chunk.end], chunk.text)

    def test_chunks_start_one_step_apart(self):
        chunks = chunk_text("p", TEXT, size=40, overlap=20)
        self.assertEqual([c.start for c in chunks[:3]], [0, 20, 40])

    def test_neighbouring_chunks_share_exactly_the_overlap(self):
        chunks = chunk_text("p", TEXT, size=40, overlap=20)
        for current, following in zip(chunks, chunks[1:]):
            self.assertEqual(current.end - following.start, 20)

    def test_there_is_no_tiny_extra_chunk_at_the_end(self):
        chunks = chunk_text("p", "x" * 60, size=40, overlap=20)
        self.assertEqual([(c.start, c.end) for c in chunks], [(0, 40), (20, 60)])

    def test_an_overlap_as_big_as_the_size_is_refused(self):
        with self.assertRaises(ValueError):
            chunk_text("p", TEXT, size=40, overlap=40)

    def test_short_text_is_one_chunk(self):
        self.assertEqual(len(chunk_text("p", "short", size=40, overlap=20)), 1)

