    Neighbouring chunks share `overlap` characters, so a sentence cut at one chunk's edge is whole in the next.
    """
    if overlap >= size:
        raise ValueError("overlap must be smaller than size")
    chunks = []
    step = size - overlap
    start = 0
    while start < len(text):
        end = min(start + size, len(text))
        chunks.append(Chunk(doc_id, start, end, text[start:end]))
        if end == len(text):
            break
        start += step
    return chunks

